entries[2888] = { ["name"] = "Eberrippchen in Biersauce", ["text"] = "Benutzen: Stellt im Verlauf von 18 sec 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 2 Ausdauer und Willenskraft." }
entries[2889] = { ["name"] = "Rezept: Eberrippchen in Biersauce", ["text"] = "Benötigt Kochkunst (10)\nBenutzen: Lehrt Euch, wie man Eberrippchen in Biersoße zubereitet.\nEberrippchen in Biersauce\nBenutzen: Stellt im Verlauf von 18 sec 61.2 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 min lang 2 Ausdauer und Willenskraft.\nBenötigt Klippeneberrippchen" }
