entries[2892] = { ["name"] = "Tödliches Gift", ["text"] = "Klassen: Schurke\nBenötigt Stufe 30\nBenutzen: Überzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 sec lang zu vergiften und (6 * 4 + 0.12 * Attack power) Naturschaden zu verursachen. Bis zu 5-mal auf einem einzelnen Ziel stapelbar. Sobald 5 Stapel erreicht sind, führt jede weitere Anwendung des tödlichen Gifts dazu, dass auch das Gift der anderen Waffe auf das Ziel wirkt. (Procchance: 30%)" }
entries[2893] = { ["name"] = "Tödliches Gift II", ["text"] = "Klassen: Schurke\nBenötigt Stufe 38\nBenutzen: Überzieht eine Waffe mit Gift, das eine Stunde lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner 12 sec lang zu vergiften und (9 * 4 + 0.12 * Attack power) Naturschaden zu verursachen. Bis zu 5-mal auf einem einzelnen Ziel stapelbar. Sobald 5 Stapel erreicht sind, führt jede weitere Anwendung des tödlichen Gifts dazu, dass auch das Gift der anderen Waffe auf das Ziel wirkt. (Procchance: 30%)" }
