entries[3089] = { ["name"] = "Foliant des Flammenstoßes", ["text"] = "Klassen: Magier\nBenötigt Stufe 16\nBenutzen: Lehrt 'Flammenstoß' (Rang 1).\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 55 to 71 Feuerschaden und zusätzlich 8 sec lang insgesamt 48 Feuerschaden zufügt." }
entries[3090] = { ["name"] = "Foliant des Frostblitzes", ["text"] = "Klassen: Magier\nBenötigt Stufe 4\nBenutzen: Lehrt 'Frostblitz' (Rang 1).\nSchleudert einen Frostblitz auf den Feind, der [Quellwert] bis [Quellwert] Frostschaden verursacht und sein Bewegungstempo 5 sec lang um 40% verringert.", ["unresolvedValues"] = true }
entries[3091] = { ["name"] = "Foliant der arkanen Intelligenz II", ["text"] = "Klassen: Magier\nBenötigt Stufe 14\nBenutzen: Lehrt Euch 'Arkane Intelligenz' (Rang 2).\nErhöht 30 min lang die Intelligenz des Ziels um 7." }
entries[3092] = { ["name"] = "Foliant des Flammenstoßes III", ["text"] = "Klassen: Magier\nBenötigt Stufe 32\nBenutzen: Lehrt 'Langsamkeit' (Rang 2).\nVerlangsamt 15 sec lang die Bewegung des Feindes um 60% und sein Angriffstempo um 54%." }
entries[3093] = { ["name"] = "Foliant des Flammenstoßes II", ["text"] = "Klassen: Magier\nBenötigt Stufe 24\nBenutzen: Lehrt 'Flammenstoß' (Rang 2).\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 100 to 126 Feuerschaden und zusätzlich 8 sec lang insgesamt 88 Feuerschaden zufügt." }
entries[3094] = { ["name"] = "Foliant des Feuerschlages II", ["text"] = "Klassen: Magier\nBenötigt Stufe 14\nBenutzen: Lehrt 'Feuerschlag' (Rang 2).\nÜberzieht den Feind mit 62 to 76 Feuerschaden." }
entries[3095] = { ["name"] = "Foliant des Feuerschlages III", ["text"] = "Klassen: Magier\nBenötigt Stufe 22\nBenutzen: Lehrt 'Feuerschlag' (Rang 3).\nÜberzieht den Feind mit 110 to 134 Feuerschaden." }
entries[3096] = { ["name"] = "Foliant des Federfalls", ["text"] = "Klassen: Magier\nBenötigt Stufe 12\nBenutzen: Lehrt 'Federfall'.\nVerlangsamt 30 sec lang das Falltempo eines befreundeten Gruppen- oder Schlachtzugsmitglieds." }
entries[3097] = { ["name"] = "Foliant des Wasserherbeizauberns II", ["text"] = "Klassen: Magier\nBenötigt Stufe 10\nBenutzen: Lehrt 'Wasser herbeizaubern' (Rang 2).\nZaubert 20 Flaschen frisches Wasser herbei und versorgt den Magier sowie seine Verbündeten mit etwas Trinkbarem.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nHerbeigezaubertes frisches Wasser\nHerbeigezauberter Gegenstand\nBenötigt Stufe 5\nBenutzen: Stellt im Verlauf von 21 sec insgesamt 437 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[3098] = { ["name"] = "Foliant der Verlangsamung", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Langsam' (Rang 1).\nVerlangsamt 10 sec lang die Bewegung des Feindes um 150% und sein Angriffstempo um 35%." }
entries[3099] = { ["name"] = "Foliant der Eisrüstung II", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Eisrüstung' (Rang 2).\nErhöht die Rüstung um 380 und den Frostwiderstand um 9. Wenn ein Feind den Zaubernden schlägt, kann 5 sec lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 25% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 min lang an." }
entries[3100] = { ["name"] = "Foliant des Blizzards II", ["text"] = "Klassen: Magier\nBenötigt Stufe 28\nBenutzen: Lehrt 'Blizzard' (Rang 2).\nEisbrocken prasseln auf das Zielgebiet nieder und verursachen 8 sec lang insgesamt [Quellwert] Frostschaden.", ["unresolvedValues"] = true }
entries[3101] = { ["name"] = "Foliant der Frostnova III", ["text"] = "Klassen: Magier\nBenötigt Stufe 40\nBenutzen: Lehrt 'Frostnova' (Rang 3).\nFügt in der Nähe des Zaubernden befindlichen Feinden [Quellwert] bis [Quellwert] Frostschaden zu und friert sie bis zu 8 sec lang ein. Erlittener Schaden kann den Effekt unterbrechen.", ["unresolvedValues"] = true }
