entries[3113] = { ["name"] = "Kodex des Heiligen Wortes: Schild", ["text"] = "Klassen: Priester\nBenötigt Stufe 6\nBenutzen: Lehrt 'Heiliges Wort: Schild' (Rang 1).\nNutzt die Seelenkraft eines befreundeten Ziels, um es mit einem Schild zu umhüllen und so 48 Schaden zu absorbieren. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
entries[3114] = { ["name"] = "Kodex des Schattenwortes: Verwirrung", ["text"] = "Klassen: Priester\nBenötigt Stufe 24\nBenutzen: Lehrt 'Schattenwort: Verwirrung' (Rang 1)." }
entries[3115] = { ["name"] = "Kodex der Erneuerung IV", ["text"] = "Klassen: Priester\nBenötigt Stufe 26\nBenutzen: Lehrt 'Erneuerung' (Rang 4).\nHeilt das Ziel im Verlauf von 15 sec um 245 Gesundheit." }
entries[3116] = { ["name"] = "Kodex des Heiligen Wortes: Schild II", ["text"] = "Klassen: Priester\nBenötigt Stufe 12\nBenutzen: Lehrt 'Heiliges Wort: Schild' (Rang 2).\nNutzt die Seelenkraft eines befreundeten Ziels, um es mit einem Schild zu umhüllen und so 94 Schaden zu absorbieren. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
