entries[3118] = { ["name"] = "Kodex der Großen Heilung", ["text"] = "Klassen: Priester\nBenötigt Stufe 40\nBenutzen: Lehrt 'Große Heilung'.\nEin langsam zu wirkender Zauber, der ein einzelnes Ziel um 924 to 1039 heilt." }
entries[3119] = { ["name"] = "Kodex des Heiligen Wortes: Schild V", ["text"] = "Klassen: Priester\nBenötigt Stufe 30\nBenutzen: Lehrt 'Heiliges Wort: Schild' (Rang 5).\nNutzt die Seelenkraft eines befreundeten Ziels, um es mit einem Schild zu umhüllen und so 313 Schaden zu absorbieren. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
entries[3120] = { ["name"] = "Kodex der heiligen Pein IV", ["text"] = "Klassen: Priester\nBenötigt Stufe 22\nBenutzen: Lehrt 'Heilige Pein' (Rang 4).\nZerschmettert einen Feind und fügt ihm 97 to 112 Heiligschaden zu." }
entries[3121] = { ["name"] = "Kodex des Levitierens", ["text"] = "Klassen: Priester\nBenötigt Stufe 34\nBenutzen: Lehrt 'Levitieren'.\nErmöglicht es dem befreundeten Gruppen- oder Schlachtzugsmitglied, ein wenig über dem Boden zu schweben. Beim Levitieren fällt das Ziel zudem mit verringertem Tempo und kann sich über Wasser bewegen. Jeglicher Schaden hebt den Effekt auf. Hält 2 min lang an." }
entries[3122] = { ["name"] = "Kodex des Heiligen Wortes: Schild III", ["text"] = "Klassen: Priester\nBenötigt Stufe 18\nBenutzen: Lehrt 'Heiliges Wort: Schild' (Rang 3).\nNutzt die Seelenkraft eines befreundeten Ziels, um es mit einem Schild zu umhüllen und so 166 Schaden zu absorbieren. Hält 30 sec lang an. Solange der Schild hält, wird das Zauberwirken durch erlittenen Schaden nicht unterbrochen. Nachdem das Ziel einmal abgeschirmt wurde, kann es 15 sec lang nicht wieder abgeschirmt werden." }
entries[3123] = { ["name"] = "Kodex des Heiligen Wortes: Seelenstärke III", ["text"] = "Klassen: Priester\nBenötigt Stufe 24\nBenutzen: Lehrt 'Heiliges Wort: Seelenstärke' (Rang 3).\nMacht erfüllt das Ziel und erhöht 30 min lang seine Ausdauer um 20." }
entries[3124] = { ["name"] = "Kodex des inneren Feuers III", ["text"] = "Klassen: Priester\nBenötigt Stufe 30\nBenutzen: Lehrt 'Inneres Feuer' (Rang 3).\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 945 erhöht. Ein erlittener Nahkampf- oder Distanzangriffstreffer verbraucht eine Aufladung. Hält 30 min lang an oder bis alle 20 Aufladungen verbraucht sind." }
entries[3125] = { ["name"] = "Schrifttafel des Schlangentotems II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 10\nBenutzen: Lehrt 'Totem der Schlange' (Rang 2).\nBeschwört 35 sec lang ein Totem der Verbrennung mit 5 Gesundheit zu Euren Füßen, das alle 2 Sekunden einen Feind im Umkreis von 20 Metern angreift und 13 to 17 Punkt(e) Feuerschaden anrichtet." }
entries[3126] = { ["name"] = "Schrifttafel des Schocks II", ["text"] = "Klassen: Schamane\nBenötigt Stufe 12\nBenutzen: Lehrt 'Schock' (Rang 2).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 61 to 65 Schaden zu." }
entries[3127] = { ["name"] = "Schrifttafel des Schocks III", ["text"] = "Klassen: Schamane\nBenötigt Stufe 20\nBenutzen: Lehrt 'Schock' (Rang 3).\nSchleudert sofort einen Blitzschlag auf das Ziel und fügt 114 to 122 Schaden zu." }
entries[3129] = { ["name"] = "Schrifttafel des Blitzschlags IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 26\nBenutzen: Lehrt 'Blitzschlag' (Rang 4).\nSchleudert einen Blitz auf das Ziel und fügt ihm 88 to 100 Naturschaden zu." }
entries[3130] = { ["name"] = "Schrifttafel der Wiederherstellung IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 24\nBenutzen: Lehrt 'Welle der Heilung' (Rang 4).\nHeilt ein befreundetes Ziel um 279 to 328." }
entries[3131] = { ["name"] = "Zerbrochene beschwerte Wurfaxt", ["text"] = "Benötigt Stufe 3" }
entries[3132] = { ["name"] = "Schrifttafel des Schmelzschlages IV", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Schmelzschlag' (Rang 4)." }
entries[3133] = { ["name"] = "Schrifttafel des Manatotems", ["text"] = "Klassen: Schamane\nBenötigt Stufe 30\nBenutzen: Lehrt 'Manatotem'.\nBeschwört ein Totem der Manaquelle mit 5 Gesundheit zu Füßen des Zaubernden. Gruppen- und Schlachtzugsmitglieder in einem Umkreis von 30 Metern erhalten alle 5 Sek. 16 Mana. Hält 5 min lang an." }
entries[3134] = { ["name"] = "Zauberfoliant des Fluchs von Mannoroth", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 4\nBenutzen: Lehrt 'Fluch der Schwäche' (Rang 1).\nDie Nahkampfangriffskraft des Ziels wird um 21 verringert, seine Rüstung um 5%. Hält 2 min lang an. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[3135] = { ["name"] = "Zerbrochene scharfe Wurfaxt", ["text"] = "Benötigt Stufe 11" }
entries[3137] = { ["name"] = "Zerbrochene tödliche Wurfaxt", ["text"] = "Benötigt Stufe 22" }
entries[3138] = { ["name"] = "Zauberfoliant des Schattenblitzes IV", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 20\nBenutzen: Lehrt 'Schattenblitz' (Rang 4).\nSendet einen schattigen Blitz zum Gegner, der 92 to 104 Schattenschaden verursacht." }
entries[3139] = { ["name"] = "Zauberfoliant der Dämonenrüstung II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 34\nBenutzen: Lehrt 'Dämonenrüstung' (Rang 2).\nSchützt den Zaubernden, erhöht die Rüstung um 660 und erhöht die durch Zauber und Effekte erzeugte Gesundheit um 20%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Hexenmeister aktiv sein. Hält 30 min an." }
entries[3140] = { ["name"] = "Zauberfoliant des Siedebluts II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 18\nBenutzen: Lehrt 'Siedeblut' (Rang 2)." }
entries[3141] = { ["name"] = "Zauberfoliant des Lebenssaugers", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 14\nBenutzen: Lehrt 'Blutsauger' (Rang 1).\nÜberträgt alle 1 Sek. 10 Gesundheit vom Ziel auf den Zaubernden. Hält 5 sec lang an." }
entries[3142] = { ["name"] = "Zauberfoliant des Fluchs von Sargeras", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 10\nBenutzen: Lehrt 'Fluch der Pein' (Rang 1).\nVerflucht das Ziel mit Pein und fügt 24 sec lang insgesamt 84 Schattenschaden zu. Zuerst wird der Schaden langsam zugefügt und nimmt dann zu, bis der Fluch seine Gesamtdauer erreicht hat. Es kann immer nur jeweils ein Fluch pro Hexenmeister auf einem beliebigen Ziel aktiv sein." }
entries[3143] = { ["name"] = "Zauberfoliant des brennenden Geistes", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 6\nBenutzen: Lehrt 'Aderlass' (Rang 1).\nWandelt ( 41 + Spirit * 1.5) Gesundheit in [ 41 * ( 1 ) + Spell power * .5 * ( 1 )] Mana um. Zaubermacht erhöht die Menge der umgewandelten Gesundheit." }
entries[3144] = { ["name"] = "Zauberfoliant des brennenden Geistes II", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 16\nBenutzen: Lehrt 'Aderlass' (Rang 2).\nWandelt ( 86 + Spirit * 1.5) Gesundheit in [ 86 * ( 1 ) + Spell power * .5 * ( 1 )] Mana um. Zaubermacht erhöht die Menge der umgewandelten Gesundheit." }
entries[3146] = { ["name"] = "Zauberfoliant des brennenden Geistes III", ["text"] = "Klassen: Hexenmeister\nBenötigt Stufe 28\nBenutzen: Lehrt 'Aderlass' (Rang 3).\nWandelt ( 159 + Spirit * 1.5) Gesundheit in [ 159 * ( 1 ) + Spell power * .5 * ( 1 )] Mana um. Zaubermacht erhöht die Menge der umgewandelten Gesundheit." }
